    env = _corridor(tc11_input)
    assert env.teams == {SOLO: TeamSpec(1, (length,), ActionSpace("discrete", n=2))}
    assert env.board == "grid"
    obs, info = env.reset(SEED)
    assert obs[SOLO].dtype == np.float32
    assert obs[SOLO].shape == (1, length)
    assert _position(obs) == 0
    assert info["steps"] == 0
    frame = env.frame()
    assert frame.dtype == np.int8
    assert frame.shape == (1, length)


