def test_goal_reward_comes_from_rewards_food(tc11_input):
    rewards = Rewards(food=10.0)
    env = _corridor(tc11_input, rewards=rewards)
    env.reset(SEED)
    result = None
    for action in tc11_input["sequences"]["a"]:
        result = env.step(_act(action))
    assert result is not None
    assert result.terminated is True
    assert result.reward[SOLO][0] == rewards.food
    assert result.info["score"] == rewards.food


@pytest.mark.intent
def test_same_seed_and_actions_give_the_same_results(tc11_input):
    actions = tc11_input["sequences"]["a"]

    def play() -> list[tuple[list[float], float, bool]]:
        env = _corridor(tc11_input)
        env.reset(SEED)
        out = []
        for action in actions:
            r = env.step(_act(action))
            out.append((r.obs[SOLO].tolist(), float(r.reward[SOLO][0]), r.terminated))
        return out

    assert play() == play()

